<script setup>
import { computed, ref } from 'vue'
import { articles, filterItems } from '../content.js'
import { bookmarks } from '../state.js'
import Icon from '../components/Icon.vue'
const query = ref(''); const category = ref('全部'); const savedOnly = ref(false)
const filtered = computed(() => filterItems(articles, query.value, category.value).filter(a => !savedOnly.value || bookmarks.value.includes(a.id)))
</script>
<template><div class="container page-space"><header class="page-heading"><div class="eyebrow">A NOTE TO KEEP</div><h1>沿途笔记<span class="serif-dot">.</span></h1><p>记录实践与设计中的发现。</p></header><div class="filter-bar"><div class="filter-chips"><button v-for="tag in ['全部','随笔','设计']" :key="tag" :class="{ active: category === tag }" :aria-pressed="category === tag" @click="category = tag">{{ tag }}</button><button :class="{ active: savedOnly }" :aria-pressed="savedOnly" @click="savedOnly = !savedOnly"><Icon name="bookmark" />已收藏</button></div><label class="search-box"><Icon name="search" /><input v-model="query" type="search" placeholder="找一篇笔记" aria-label="搜索笔记"></label></div><p class="result-count" aria-live="polite">{{ filtered.length }} 篇笔记 <span>收藏仅保存在当前浏览器</span></p><TransitionGroup name="cards" tag="div" class="article-grid"><RouterLink v-for="article in filtered" :key="article.id" :to="`/journal/${article.id}`" class="article-card"><div class="article-cover" :class="`cover-${article.cover}`" aria-hidden="true"><span>{{ article.cover === 'seed' ? '栖' : article.cover === 'grid' ? 'make it clear.' : 'less, but alive.' }}</span><i></i><small>QIWULI / JOURNAL</small></div><div class="article-card-body"><div class="entry-meta">{{ article.category }} · {{ article.minutes }} 分钟</div><h2>{{ article.title }}</h2><p>{{ article.summary }}</p><div class="article-card-footer"><time :datetime="article.date">{{ article.date.replaceAll('-', '.') }}</time><Icon :name="bookmarks.includes(article.id) ? 'bookmark' : 'diagonal'" /></div></div></RouterLink></TransitionGroup><div v-if="!filtered.length" class="empty-state"><Icon name="bookmark" /><h2>{{ savedOnly ? '这里还没有符合条件的收藏' : '暂时没找到这篇笔记' }}</h2><p>试试其他关键词，或浏览全部笔记。</p><button class="button secondary" @click="savedOnly = false; query = ''; category = '全部'">浏览全部笔记</button></div></div></template>
